macro_rules! impl_242 {
    () => {
        deps!();
        impl Config { # [doc = " Return a new default lazy DFA builder configuration."] pub fn new () -> Config { Config :: default () } # [doc = " Set the desired match semantics."] # [doc = ""] # [doc = " The default is [`MatchKind::LeftmostFirst`], which corresponds to the"] # [doc = " match semantics of Perl-like regex engines. That is, when multiple"] # [doc = " patterns would match at the same leftmost position, the pattern that"] # [doc = " appears first in the concrete syntax is chosen."] # [doc = ""] # [doc = " Currently, the only other kind of match semantics supported is"] # [doc = " [`MatchKind::All`]. This corresponds to classical DFA construction"] # [doc = " where all possible matches are added to the lazy DFA."] # [doc = ""] # [doc = " Typically, `All` is used when one wants to execute an overlapping"] # [doc = " search and `LeftmostFirst` otherwise. In particular, it rarely makes"] # [doc = " sense to use `All` with the various \"leftmost\" find routines, since the"] # [doc = " leftmost routines depend on the `LeftmostFirst` automata construction"] # [doc = " strategy. Specifically, `LeftmostFirst` adds dead states to the"] # [doc = " lazy DFA as a way to terminate the search and report a match."] # [doc = " `LeftmostFirst` also supports non-greedy matches using this strategy"] # [doc = " where as `All` does not."] # [doc = ""] # [doc = " # Example: overlapping search"] # [doc = ""] # [doc = " This example shows the typical use of `MatchKind::All`, which is to"] # [doc = " report overlapping matches."] # [doc = ""] # [doc = " ```"] # [doc = " # if cfg!(miri) { return Ok(()); } // miri takes too long"] # [doc = " use regex_automata::{"] # [doc = "     hybrid::dfa::{DFA, OverlappingState},"] # [doc = "     HalfMatch, Input, MatchKind,"] # [doc = " };"] # [doc = ""] # [doc = " let dfa = DFA::builder()"] # [doc = "     .configure(DFA::config().match_kind(MatchKind::All))"] # [doc = "     .build_many(&[r\"\\w+$\", r\"\\S+$\"])?;"] # [doc = " let mut cache = dfa.create_cache();"] # [doc = " let haystack = \"@foo\";"] # [doc = " let mut state = OverlappingState::start();"] # [doc = ""] # [doc = " let expected = Some(HalfMatch::must(1, 4));"] # [doc = " dfa.try_search_overlapping_fwd("] # [doc = "     &mut cache, &Input::new(haystack), &mut state,"] # [doc = " )?;"] # [doc = " assert_eq!(expected, state.get_match());"] # [doc = ""] # [doc = " // The first pattern also matches at the same position, so re-running"] # [doc = " // the search will yield another match. Notice also that the first"] # [doc = " // pattern is returned after the second. This is because the second"] # [doc = " // pattern begins its match before the first, is therefore an earlier"] # [doc = " // match and is thus reported first."] # [doc = " let expected = Some(HalfMatch::must(0, 4));"] # [doc = " dfa.try_search_overlapping_fwd("] # [doc = "     &mut cache, &Input::new(haystack), &mut state,"] # [doc = " )?;"] # [doc = " assert_eq!(expected, state.get_match());"] # [doc = ""] # [doc = " # Ok::<(), Box<dyn std::error::Error>>(())"] # [doc = " ```"] # [doc = ""] # [doc = " # Example: reverse automaton to find start of match"] # [doc = ""] # [doc = " Another example for using `MatchKind::All` is for constructing a"] # [doc = " reverse automaton to find the start of a match. `All` semantics are"] # [doc = " used for this in order to find the longest possible match, which"] # [doc = " corresponds to the leftmost starting position."] # [doc = ""] # [doc = " Note that if you need the starting position then"] # [doc = " [`hybrid::regex::Regex`](crate::hybrid::regex::Regex) will handle this"] # [doc = " for you, so it's usually not necessary to do this yourself."] # [doc = ""] # [doc = " ```"] # [doc = " use regex_automata::{"] # [doc = "     hybrid::dfa::DFA,"] # [doc = "     nfa::thompson::NFA,"] # [doc = "     Anchored, HalfMatch, Input, MatchKind,"] # [doc = " };"] # [doc = ""] # [doc = " let input = Input::new(\"123foobar456\");"] # [doc = " let pattern = r\"[a-z]+r\";"] # [doc = ""] # [doc = " let dfa_fwd = DFA::new(pattern)?;"] # [doc = " let dfa_rev = DFA::builder()"] # [doc = "     .thompson(NFA::config().reverse(true))"] # [doc = "     .configure(DFA::config().match_kind(MatchKind::All))"] # [doc = "     .build(pattern)?;"] # [doc = " let mut cache_fwd = dfa_fwd.create_cache();"] # [doc = " let mut cache_rev = dfa_rev.create_cache();"] # [doc = ""] # [doc = " let expected_fwd = HalfMatch::must(0, 9);"] # [doc = " let expected_rev = HalfMatch::must(0, 3);"] # [doc = " let got_fwd = dfa_fwd.try_search_fwd(&mut cache_fwd, &input)?.unwrap();"] # [doc = " // Here we don't specify the pattern to search for since there's only"] # [doc = " // one pattern and we're doing a leftmost search. But if this were an"] # [doc = " // overlapping search, you'd need to specify the pattern that matched"] # [doc = " // in the forward direction. (Otherwise, you might wind up finding the"] # [doc = " // starting position of a match of some other pattern.) That in turn"] # [doc = " // requires building the reverse automaton with starts_for_each_pattern"] # [doc = " // enabled."] # [doc = " let input = input"] # [doc = "     .clone()"] # [doc = "     .range(..got_fwd.offset())"] # [doc = "     .anchored(Anchored::Yes);"] # [doc = " let got_rev = dfa_rev.try_search_rev(&mut cache_rev, &input)?.unwrap();"] # [doc = " assert_eq!(expected_fwd, got_fwd);"] # [doc = " assert_eq!(expected_rev, got_rev);"] # [doc = ""] # [doc = " # Ok::<(), Box<dyn std::error::Error>>(())"] # [doc = " ```"] pub fn match_kind (mut self , kind : MatchKind) -> Config { self . match_kind = Some (kind) ; self } # [doc = " Set a prefilter to be used whenever a start state is entered."] # [doc = ""] # [doc = " A [`Prefilter`] in this context is meant to accelerate searches by"] # [doc = " looking for literal prefixes that every match for the corresponding"] # [doc = " pattern (or patterns) must start with. Once a prefilter produces a"] # [doc = " match, the underlying search routine continues on to try and confirm"] # [doc = " the match."] # [doc = ""] # [doc = " Be warned that setting a prefilter does not guarantee that the search"] # [doc = " will be faster. While it's usually a good bet, if the prefilter"] # [doc = " produces a lot of false positive candidates (i.e., positions matched"] # [doc = " by the prefilter but not by the regex), then the overall result can"] # [doc = " be slower than if you had just executed the regex engine without any"] # [doc = " prefilters."] # [doc = ""] # [doc = " Note that unless [`Config::specialize_start_states`] has been"] # [doc = " explicitly set, then setting this will also enable (when `pre` is"] # [doc = " `Some`) or disable (when `pre` is `None`) start state specialization."] # [doc = " This occurs because without start state specialization, a prefilter"] # [doc = " is likely to be less effective. And without a prefilter, start state"] # [doc = " specialization is usually pointless."] # [doc = ""] # [doc = " By default no prefilter is set."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " ```"] # [doc = " use regex_automata::{"] # [doc = "     hybrid::dfa::DFA,"] # [doc = "     util::prefilter::Prefilter,"] # [doc = "     Input, HalfMatch, MatchKind,"] # [doc = " };"] # [doc = ""] # [doc = " let pre = Prefilter::new(MatchKind::LeftmostFirst, &[\"foo\", \"bar\"]);"] # [doc = " let re = DFA::builder()"] # [doc = "     .configure(DFA::config().prefilter(pre))"] # [doc = "     .build(r\"(foo|bar)[a-z]+\")?;"] # [doc = " let mut cache = re.create_cache();"] # [doc = " let input = Input::new(\"foo1 barfox bar\");"] # [doc = " assert_eq!("] # [doc = "     Some(HalfMatch::must(0, 11)),"] # [doc = "     re.try_search_fwd(&mut cache, &input)?,"] # [doc = " );"] # [doc = ""] # [doc = " # Ok::<(), Box<dyn std::error::Error>>(())"] # [doc = " ```"] # [doc = ""] # [doc = " Be warned though that an incorrect prefilter can lead to incorrect"] # [doc = " results!"] # [doc = ""] # [doc = " ```"] # [doc = " use regex_automata::{"] # [doc = "     hybrid::dfa::DFA,"] # [doc = "     util::prefilter::Prefilter,"] # [doc = "     Input, HalfMatch, MatchKind,"] # [doc = " };"] # [doc = ""] # [doc = " let pre = Prefilter::new(MatchKind::LeftmostFirst, &[\"foo\", \"car\"]);"] # [doc = " let re = DFA::builder()"] # [doc = "     .configure(DFA::config().prefilter(pre))"] # [doc = "     .build(r\"(foo|bar)[a-z]+\")?;"] # [doc = " let mut cache = re.create_cache();"] # [doc = " let input = Input::new(\"foo1 barfox bar\");"] # [doc = " assert_eq!("] # [doc = "     // No match reported even though there clearly is one!"] # [doc = "     None,"] # [doc = "     re.try_search_fwd(&mut cache, &input)?,"] # [doc = " );"] # [doc = ""] # [doc = " # Ok::<(), Box<dyn std::error::Error>>(())"] # [doc = " ```"] pub fn prefilter (mut self , pre : Option < Prefilter >) -> Config { self . pre = Some (pre) ; if self . specialize_start_states . is_none () { self . specialize_start_states = Some (self . get_prefilter () . is_some ()) ; } self } # [doc = " Whether to compile a separate start state for each pattern in the"] # [doc = " lazy DFA."] # [doc = ""] # [doc = " When enabled, a separate **anchored** start state is added for each"] # [doc = " pattern in the lazy DFA. When this start state is used, then the DFA"] # [doc = " will only search for matches for the pattern specified, even if there"] # [doc = " are other patterns in the DFA."] # [doc = ""] # [doc = " The main downside of this option is that it can potentially increase"] # [doc = " the size of the DFA and/or increase the time it takes to build the"] # [doc = " DFA at search time. However, since this is configuration for a lazy"] # [doc = " DFA, these states aren't actually built unless they're used. Enabling"] # [doc = " this isn't necessarily free, however, as it may result in higher cache"] # [doc = " usage."] # [doc = ""] # [doc = " There are a few reasons one might want to enable this (it's disabled"] # [doc = " by default):"] # [doc = ""] # [doc = " 1. When looking for the start of an overlapping match (using a reverse"] # [doc = " DFA), doing it correctly requires starting the reverse search using the"] # [doc = " starting state of the pattern that matched in the forward direction."] # [doc = " Indeed, when building a [`Regex`](crate::hybrid::regex::Regex), it"] # [doc = " will automatically enable this option when building the reverse DFA"] # [doc = " internally."] # [doc = " 2. When you want to use a DFA with multiple patterns to both search"] # [doc = " for matches of any pattern or to search for anchored matches of one"] # [doc = " particular pattern while using the same DFA. (Otherwise, you would need"] # [doc = " to compile a new DFA for each pattern.)"] # [doc = ""] # [doc = " By default this is disabled."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " This example shows how to use this option to permit the same lazy DFA"] # [doc = " to run both general searches for any pattern and anchored searches for"] # [doc = " a specific pattern."] # [doc = ""] # [doc = " ```"] # [doc = " use regex_automata::{"] # [doc = "     hybrid::dfa::DFA,"] # [doc = "     Anchored, HalfMatch, Input, PatternID,"] # [doc = " };"] # [doc = ""] # [doc = " let dfa = DFA::builder()"] # [doc = "     .configure(DFA::config().starts_for_each_pattern(true))"] # [doc = "     .build_many(&[r\"[a-z0-9]{6}\", r\"[a-z][a-z0-9]{5}\"])?;"] # [doc = " let mut cache = dfa.create_cache();"] # [doc = " let haystack = \"bar foo123\";"] # [doc = ""] # [doc = " // Here's a normal unanchored search that looks for any pattern."] # [doc = " let expected = HalfMatch::must(0, 10);"] # [doc = " let input = Input::new(haystack);"] # [doc = " assert_eq!(Some(expected), dfa.try_search_fwd(&mut cache, &input)?);"] # [doc = " // We can also do a normal anchored search for any pattern. Since it's"] # [doc = " // an anchored search, we position the start of the search where we"] # [doc = " // know the match will begin."] # [doc = " let expected = HalfMatch::must(0, 10);"] # [doc = " let input = Input::new(haystack).range(4..);"] # [doc = " assert_eq!(Some(expected), dfa.try_search_fwd(&mut cache, &input)?);"] # [doc = " // Since we compiled anchored start states for each pattern, we can"] # [doc = " // also look for matches of other patterns explicitly, even if a"] # [doc = " // different pattern would have normally matched."] # [doc = " let expected = HalfMatch::must(1, 10);"] # [doc = " let input = Input::new(haystack)"] # [doc = "     .range(4..)"] # [doc = "     .anchored(Anchored::Pattern(PatternID::must(1)));"] # [doc = " assert_eq!(Some(expected), dfa.try_search_fwd(&mut cache, &input)?);"] # [doc = ""] # [doc = " # Ok::<(), Box<dyn std::error::Error>>(())"] # [doc = " ```"] pub fn starts_for_each_pattern (mut self , yes : bool) -> Config { self . starts_for_each_pattern = Some (yes) ; self } # [doc = " Whether to attempt to shrink the size of the lazy DFA's alphabet or"] # [doc = " not."] # [doc = ""] # [doc = " This option is enabled by default and should never be disabled unless"] # [doc = " one is debugging the lazy DFA."] # [doc = ""] # [doc = " When enabled, the lazy DFA will use a map from all possible bytes"] # [doc = " to their corresponding equivalence class. Each equivalence class"] # [doc = " represents a set of bytes that does not discriminate between a match"] # [doc = " and a non-match in the DFA. For example, the pattern `[ab]+` has at"] # [doc = " least two equivalence classes: a set containing `a` and `b` and a set"] # [doc = " containing every byte except for `a` and `b`. `a` and `b` are in the"] # [doc = " same equivalence classes because they never discriminate between a"] # [doc = " match and a non-match."] # [doc = ""] # [doc = " The advantage of this map is that the size of the transition table"] # [doc = " can be reduced drastically from `#states * 256 * sizeof(LazyStateID)`"] # [doc = " to `#states * k * sizeof(LazyStateID)` where `k` is the number of"] # [doc = " equivalence classes (rounded up to the nearest power of 2). As a"] # [doc = " result, total space usage can decrease substantially. Moreover, since a"] # [doc = " smaller alphabet is used, DFA compilation during search becomes faster"] # [doc = " as well since it will potentially be able to reuse a single transition"] # [doc = " for multiple bytes."] # [doc = ""] # [doc = " **WARNING:** This is only useful for debugging lazy DFAs. Disabling"] # [doc = " this does not yield any speed advantages. Namely, even when this is"] # [doc = " disabled, a byte class map is still used while searching. The only"] # [doc = " difference is that every byte will be forced into its own distinct"] # [doc = " equivalence class. This is useful for debugging the actual generated"] # [doc = " transitions because it lets one see the transitions defined on actual"] # [doc = " bytes instead of the equivalence classes."] pub fn byte_classes (mut self , yes : bool) -> Config { self . byte_classes = Some (yes) ; self } # [doc = " Heuristically enable Unicode word boundaries."] # [doc = ""] # [doc = " When set, this will attempt to implement Unicode word boundaries as if"] # [doc = " they were ASCII word boundaries. This only works when the search input"] # [doc = " is ASCII only. If a non-ASCII byte is observed while searching, then a"] # [doc = " [`MatchError::quit`] error is returned."] # [doc = ""] # [doc = " A possible alternative to enabling this option is to simply use an"] # [doc = " ASCII word boundary, e.g., via `(?-u:\\b)`. The main reason to use this"] # [doc = " option is if you absolutely need Unicode support. This option lets one"] # [doc = " use a fast search implementation (a DFA) for some potentially very"] # [doc = " common cases, while providing the option to fall back to some other"] # [doc = " regex engine to handle the general case when an error is returned."] # [doc = ""] # [doc = " If the pattern provided has no Unicode word boundary in it, then this"] # [doc = " option has no effect. (That is, quitting on a non-ASCII byte only"] # [doc = " occurs when this option is enabled _and_ a Unicode word boundary is"] # [doc = " present in the pattern.)"] # [doc = ""] # [doc = " This is almost equivalent to setting all non-ASCII bytes to be quit"] # [doc = " bytes. The only difference is that this will cause non-ASCII bytes to"] # [doc = " be quit bytes _only_ when a Unicode word boundary is present in the"] # [doc = " pattern."] # [doc = ""] # [doc = " When enabling this option, callers _must_ be prepared to"] # [doc = " handle a [`MatchError`] error during search. When using a"] # [doc = " [`Regex`](crate::hybrid::regex::Regex), this corresponds to using the"] # [doc = " `try_` suite of methods. Alternatively, if callers can guarantee that"] # [doc = " their input is ASCII only, then a [`MatchError::quit`] error will never"] # [doc = " be returned while searching."] # [doc = ""] # [doc = " This is disabled by default."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " This example shows how to heuristically enable Unicode word boundaries"] # [doc = " in a pattern. It also shows what happens when a search comes across a"] # [doc = " non-ASCII byte."] # [doc = ""] # [doc = " ```"] # [doc = " use regex_automata::{"] # [doc = "     hybrid::dfa::DFA,"] # [doc = "     HalfMatch, Input, MatchError,"] # [doc = " };"] # [doc = ""] # [doc = " let dfa = DFA::builder()"] # [doc = "     .configure(DFA::config().unicode_word_boundary(true))"] # [doc = "     .build(r\"\\b[0-9]+\\b\")?;"] # [doc = " let mut cache = dfa.create_cache();"] # [doc = ""] # [doc = " // The match occurs before the search ever observes the snowman"] # [doc = " // character, so no error occurs."] # [doc = " let haystack = \"foo 123  ☃\";"] # [doc = " let expected = Some(HalfMatch::must(0, 7));"] # [doc = " let got = dfa.try_search_fwd(&mut cache, &Input::new(haystack))?;"] # [doc = " assert_eq!(expected, got);"] # [doc = ""] # [doc = " // Notice that this search fails, even though the snowman character"] # [doc = " // occurs after the ending match offset. This is because search"] # [doc = " // routines read one byte past the end of the search to account for"] # [doc = " // look-around, and indeed, this is required here to determine whether"] # [doc = " // the trailing \\b matches."] # [doc = " let haystack = \"foo 123 ☃\";"] # [doc = " let expected = MatchError::quit(0xE2, 8);"] # [doc = " let got = dfa.try_search_fwd(&mut cache, &Input::new(haystack));"] # [doc = " assert_eq!(Err(expected), got);"] # [doc = ""] # [doc = " // Another example is executing a search where the span of the haystack"] # [doc = " // we specify is all ASCII, but there is non-ASCII just before it. This"] # [doc = " // correctly also reports an error."] # [doc = " let input = Input::new(\"β123\").range(2..);"] # [doc = " let expected = MatchError::quit(0xB2, 1);"] # [doc = " let got = dfa.try_search_fwd(&mut cache, &input);"] # [doc = " assert_eq!(Err(expected), got);"] # [doc = ""] # [doc = " // And similarly for the trailing word boundary."] # [doc = " let input = Input::new(\"123β\").range(..3);"] # [doc = " let expected = MatchError::quit(0xCE, 3);"] # [doc = " let got = dfa.try_search_fwd(&mut cache, &input);"] # [doc = " assert_eq!(Err(expected), got);"] # [doc = ""] # [doc = " # Ok::<(), Box<dyn std::error::Error>>(())"] # [doc = " ```"] pub fn unicode_word_boundary (mut self , yes : bool) -> Config { self . unicode_word_boundary = Some (yes) ; self } # [doc = " Add a \"quit\" byte to the lazy DFA."] # [doc = ""] # [doc = " When a quit byte is seen during search time, then search will return a"] # [doc = " [`MatchError::quit`] error indicating the offset at which the search"] # [doc = " stopped."] # [doc = ""] # [doc = " A quit byte will always overrule any other aspects of a regex. For"] # [doc = " example, if the `x` byte is added as a quit byte and the regex `\\w` is"] # [doc = " used, then observing `x` will cause the search to quit immediately"] # [doc = " despite the fact that `x` is in the `\\w` class."] # [doc = ""] # [doc = " This mechanism is primarily useful for heuristically enabling certain"] # [doc = " features like Unicode word boundaries in a DFA. Namely, if the input"] # [doc = " to search is ASCII, then a Unicode word boundary can be implemented"] # [doc = " via an ASCII word boundary with no change in semantics. Thus, a DFA"] # [doc = " can attempt to match a Unicode word boundary but give up as soon as it"] # [doc = " observes a non-ASCII byte. Indeed, if callers set all non-ASCII bytes"] # [doc = " to be quit bytes, then Unicode word boundaries will be permitted when"] # [doc = " building lazy DFAs. Of course, callers should enable"] # [doc = " [`Config::unicode_word_boundary`] if they want this behavior instead."] # [doc = " (The advantage being that non-ASCII quit bytes will only be added if a"] # [doc = " Unicode word boundary is in the pattern.)"] # [doc = ""] # [doc = " When enabling this option, callers _must_ be prepared to"] # [doc = " handle a [`MatchError`] error during search. When using a"] # [doc = " [`Regex`](crate::hybrid::regex::Regex), this corresponds to using the"] # [doc = " `try_` suite of methods."] # [doc = ""] # [doc = " By default, there are no quit bytes set."] # [doc = ""] # [doc = " # Panics"] # [doc = ""] # [doc = " This panics if heuristic Unicode word boundaries are enabled and any"] # [doc = " non-ASCII byte is removed from the set of quit bytes. Namely, enabling"] # [doc = " Unicode word boundaries requires setting every non-ASCII byte to a quit"] # [doc = " byte. So if the caller attempts to undo any of that, then this will"] # [doc = " panic."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " This example shows how to cause a search to terminate if it sees a"] # [doc = " `\\n` byte. This could be useful if, for example, you wanted to prevent"] # [doc = " a user supplied pattern from matching across a line boundary."] # [doc = ""] # [doc = " ```"] # [doc = " # if cfg!(miri) { return Ok(()); } // miri takes too long"] # [doc = " use regex_automata::{hybrid::dfa::DFA, MatchError, Input};"] # [doc = ""] # [doc = " let dfa = DFA::builder()"] # [doc = "     .configure(DFA::config().quit(b'\\n', true))"] # [doc = "     .build(r\"foo\\p{any}+bar\")?;"] # [doc = " let mut cache = dfa.create_cache();"] # [doc = ""] # [doc = " let haystack = \"foo\\nbar\";"] # [doc = " // Normally this would produce a match, since \\p{any} contains '\\n'."] # [doc = " // But since we instructed the automaton to enter a quit state if a"] # [doc = " // '\\n' is observed, this produces a match error instead."] # [doc = " let expected = MatchError::quit(b'\\n', 3);"] # [doc = " let got = dfa.try_search_fwd("] # [doc = "     &mut cache,"] # [doc = "     &Input::new(haystack),"] # [doc = " ).unwrap_err();"] # [doc = " assert_eq!(expected, got);"] # [doc = ""] # [doc = " # Ok::<(), Box<dyn std::error::Error>>(())"] # [doc = " ```"] pub fn quit (mut self , byte : u8 , yes : bool) -> Config { if self . get_unicode_word_boundary () && ! byte . is_ascii () && ! yes { panic ! ("cannot set non-ASCII byte to be non-quit when \
                 Unicode word boundaries are enabled") ; } if self . quitset . is_none () { self . quitset = Some (ByteSet :: empty ()) ; } if yes { self . quitset . as_mut () . unwrap () . add (byte) ; } else { self . quitset . as_mut () . unwrap () . remove (byte) ; } self } # [doc = " Enable specializing start states in the lazy DFA."] # [doc = ""] # [doc = " When start states are specialized, an implementor of a search routine"] # [doc = " using a lazy DFA can tell when the search has entered a starting state."] # [doc = " When start states aren't specialized, then it is impossible to know"] # [doc = " whether the search has entered a start state."] # [doc = ""] # [doc = " Ideally, this option wouldn't need to exist and we could always"] # [doc = " specialize start states. The problem is that start states can be quite"] # [doc = " active. This in turn means that an efficient search routine is likely"] # [doc = " to ping-pong between a heavily optimized hot loop that handles most"] # [doc = " states and to a less optimized specialized handling of start states."] # [doc = " This causes branches to get heavily mispredicted and overall can"] # [doc = " materially decrease throughput. Therefore, specializing start states"] # [doc = " should only be enabled when it is needed."] # [doc = ""] # [doc = " Knowing whether a search is in a start state is typically useful when a"] # [doc = " prefilter is active for the search. A prefilter is typically only run"] # [doc = " when in a start state and a prefilter can greatly accelerate a search."] # [doc = " Therefore, the possible cost of specializing start states is worth it"] # [doc = " in this case. Otherwise, if you have no prefilter, there is likely no"] # [doc = " reason to specialize start states."] # [doc = ""] # [doc = " This is disabled by default, but note that it is automatically"] # [doc = " enabled (or disabled) if [`Config::prefilter`] is set. Namely, unless"] # [doc = " `specialize_start_states` has already been set, [`Config::prefilter`]"] # [doc = " will automatically enable or disable it based on whether a prefilter"] # [doc = " is present or not, respectively. This is done because a prefilter's"] # [doc = " effectiveness is rooted in being executed whenever the DFA is in a"] # [doc = " start state, and that's only possible to do when they are specialized."] # [doc = ""] # [doc = " Note that it is plausibly reasonable to _disable_ this option"] # [doc = " explicitly while _enabling_ a prefilter. In that case, a prefilter"] # [doc = " will still be run at the beginning of a search, but never again. This"] # [doc = " in theory could strike a good balance if you're in a situation where a"] # [doc = " prefilter is likely to produce many false positive candidates."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " This example shows how to enable start state specialization and then"] # [doc = " shows how to check whether a state is a start state or not."] # [doc = ""] # [doc = " ```"] # [doc = " use regex_automata::{hybrid::dfa::DFA, MatchError, Input};"] # [doc = ""] # [doc = " let dfa = DFA::builder()"] # [doc = "     .configure(DFA::config().specialize_start_states(true))"] # [doc = "     .build(r\"[a-z]+\")?;"] # [doc = " let mut cache = dfa.create_cache();"] # [doc = ""] # [doc = " let haystack = \"123 foobar 4567\".as_bytes();"] # [doc = " let sid = dfa.start_state_forward(&mut cache, &Input::new(haystack))?;"] # [doc = " // The ID returned by 'start_state_forward' will always be tagged as"] # [doc = " // a start state when start state specialization is enabled."] # [doc = " assert!(sid.is_tagged());"] # [doc = " assert!(sid.is_start());"] # [doc = ""] # [doc = " # Ok::<(), Box<dyn std::error::Error>>(())"] # [doc = " ```"] # [doc = ""] # [doc = " Compare the above with the default lazy DFA configuration where"] # [doc = " start states are _not_ specialized. In this case, the start state"] # [doc = " is not tagged and `sid.is_start()` returns false."] # [doc = ""] # [doc = " ```"] # [doc = " use regex_automata::{hybrid::dfa::DFA, MatchError, Input};"] # [doc = ""] # [doc = " let dfa = DFA::new(r\"[a-z]+\")?;"] # [doc = " let mut cache = dfa.create_cache();"] # [doc = ""] # [doc = " let haystack = \"123 foobar 4567\".as_bytes();"] # [doc = " let sid = dfa.start_state_forward(&mut cache, &Input::new(haystack))?;"] # [doc = " // Start states are not tagged in the default configuration!"] # [doc = " assert!(!sid.is_tagged());"] # [doc = " assert!(!sid.is_start());"] # [doc = ""] # [doc = " # Ok::<(), Box<dyn std::error::Error>>(())"] # [doc = " ```"] pub fn specialize_start_states (mut self , yes : bool) -> Config { self . specialize_start_states = Some (yes) ; self } # [doc = " Sets the maximum amount of heap memory, in bytes, to allocate to the"] # [doc = " cache for use during a lazy DFA search. If the lazy DFA would otherwise"] # [doc = " use more heap memory, then, depending on other configuration knobs,"] # [doc = " either stop the search and return an error or clear the cache and"] # [doc = " continue the search."] # [doc = ""] # [doc = " The default cache capacity is some \"reasonable\" number that will"] # [doc = " accommodate most regular expressions. You may find that if you need"] # [doc = " to build a large DFA then it may be necessary to increase the cache"] # [doc = " capacity."] # [doc = ""] # [doc = " Note that while building a lazy DFA will do a \"minimum\" check to ensure"] # [doc = " the capacity is big enough, this is more or less about correctness."] # [doc = " If the cache is bigger than the minimum but still \"too small,\" then the"] # [doc = " lazy DFA could wind up spending a lot of time clearing the cache and"] # [doc = " recomputing transitions, thus negating the performance benefits of a"] # [doc = " lazy DFA. Thus, setting the cache capacity is mostly an experimental"] # [doc = " endeavor. For most common patterns, however, the default should be"] # [doc = " sufficient."] # [doc = ""] # [doc = " For more details on how the lazy DFA's cache is used, see the"] # [doc = " documentation for [`Cache`]."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " This example shows what happens if the configured cache capacity is"] # [doc = " too small. In such cases, one can override the cache capacity to make"] # [doc = " it bigger. Alternatively, one might want to use less memory by setting"] # [doc = " a smaller cache capacity."] # [doc = ""] # [doc = " ```"] # [doc = " # if cfg!(miri) { return Ok(()); } // miri takes too long"] # [doc = " use regex_automata::{hybrid::dfa::DFA, HalfMatch, Input};"] # [doc = ""] # [doc = " let pattern = r\"\\p{L}{1000}\";"] # [doc = ""] # [doc = " // The default cache capacity is likely too small to deal with regexes"] # [doc = " // that are very large. Large repetitions of large Unicode character"] # [doc = " // classes are a common way to make very large regexes."] # [doc = " let _ = DFA::new(pattern).unwrap_err();"] # [doc = " // Bump up the capacity to something bigger."] # [doc = " let dfa = DFA::builder()"] # [doc = "     .configure(DFA::config().cache_capacity(100 * (1<<20))) // 100 MB"] # [doc = "     .build(pattern)?;"] # [doc = " let mut cache = dfa.create_cache();"] # [doc = ""] # [doc = " let haystack = \"ͰͲͶͿΆΈΉΊΌΎΏΑΒΓΔΕΖΗΘΙ\".repeat(50);"] # [doc = " let expected = Some(HalfMatch::must(0, 2000));"] # [doc = " let got = dfa.try_search_fwd(&mut cache, &Input::new(&haystack))?;"] # [doc = " assert_eq!(expected, got);"] # [doc = ""] # [doc = " # Ok::<(), Box<dyn std::error::Error>>(())"] # [doc = " ```"] pub fn cache_capacity (mut self , bytes : usize) -> Config { self . cache_capacity = Some (bytes) ; self } # [doc = " Configures construction of a lazy DFA to use the minimum cache capacity"] # [doc = " if the configured capacity is otherwise too small for the provided NFA."] # [doc = ""] # [doc = " This is useful if you never want lazy DFA construction to fail because"] # [doc = " of a capacity that is too small."] # [doc = ""] # [doc = " In general, this option is typically not a good idea. In particular,"] # [doc = " while a minimum cache capacity does permit the lazy DFA to function"] # [doc = " where it otherwise couldn't, it's plausible that it may not function"] # [doc = " well if it's constantly running out of room. In that case, the speed"] # [doc = " advantages of the lazy DFA may be negated. On the other hand, the"] # [doc = " \"minimum\" cache capacity computed may not be completely accurate and"] # [doc = " could actually be bigger than what is really necessary. Therefore, it"] # [doc = " is plausible that using the minimum cache capacity could still result"] # [doc = " in very good performance."] # [doc = ""] # [doc = " This is disabled by default."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " This example shows what happens if the configured cache capacity is"] # [doc = " too small. In such cases, one could override the capacity explicitly."] # [doc = " An alternative, demonstrated here, let's us force construction to use"] # [doc = " the minimum cache capacity if the configured capacity is otherwise"] # [doc = " too small."] # [doc = ""] # [doc = " ```"] # [doc = " # if cfg!(miri) { return Ok(()); } // miri takes too long"] # [doc = " use regex_automata::{hybrid::dfa::DFA, HalfMatch, Input};"] # [doc = ""] # [doc = " let pattern = r\"\\p{L}{1000}\";"] # [doc = ""] # [doc = " // The default cache capacity is likely too small to deal with regexes"] # [doc = " // that are very large. Large repetitions of large Unicode character"] # [doc = " // classes are a common way to make very large regexes."] # [doc = " let _ = DFA::new(pattern).unwrap_err();"] # [doc = " // Configure construction such it automatically selects the minimum"] # [doc = " // cache capacity if it would otherwise be too small."] # [doc = " let dfa = DFA::builder()"] # [doc = "     .configure(DFA::config().skip_cache_capacity_check(true))"] # [doc = "     .build(pattern)?;"] # [doc = " let mut cache = dfa.create_cache();"] # [doc = ""] # [doc = " let haystack = \"ͰͲͶͿΆΈΉΊΌΎΏΑΒΓΔΕΖΗΘΙ\".repeat(50);"] # [doc = " let expected = Some(HalfMatch::must(0, 2000));"] # [doc = " let got = dfa.try_search_fwd(&mut cache, &Input::new(&haystack))?;"] # [doc = " assert_eq!(expected, got);"] # [doc = ""] # [doc = " # Ok::<(), Box<dyn std::error::Error>>(())"] # [doc = " ```"] pub fn skip_cache_capacity_check (mut self , yes : bool) -> Config { self . skip_cache_capacity_check = Some (yes) ; self } # [doc = " Configure a lazy DFA search to quit after a certain number of cache"] # [doc = " clearings."] # [doc = ""] # [doc = " When a minimum is set, then a lazy DFA search will *possibly* \"give"] # [doc = " up\" after the minimum number of cache clearings has occurred. This is"] # [doc = " typically useful in scenarios where callers want to detect whether the"] # [doc = " lazy DFA search is \"efficient\" or not. If the cache is cleared too many"] # [doc = " times, this is a good indicator that it is not efficient, and thus, the"] # [doc = " caller may wish to use some other regex engine."] # [doc = ""] # [doc = " Note that the number of times a cache is cleared is a property of"] # [doc = " the cache itself. Thus, if a cache is used in a subsequent search"] # [doc = " with a similarly configured lazy DFA, then it could cause the"] # [doc = " search to \"give up\" if the cache needed to be cleared, depending"] # [doc = " on its internal count and configured minimum. The cache clear"] # [doc = " count can only be reset to `0` via [`DFA::reset_cache`] (or"] # [doc = " [`Regex::reset_cache`](crate::hybrid::regex::Regex::reset_cache) if"] # [doc = " you're using the `Regex` API)."] # [doc = ""] # [doc = " By default, no minimum is configured. Thus, a lazy DFA search will"] # [doc = " never give up due to cache clearings. If you do set this option, you"] # [doc = " might consider also setting [`Config::minimum_bytes_per_state`] in"] # [doc = " order for the lazy DFA to take efficiency into account before giving"] # [doc = " up."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " This example uses a somewhat pathological configuration to demonstrate"] # [doc = " the _possible_ behavior of cache clearing and how it might result"] # [doc = " in a search that returns an error."] # [doc = ""] # [doc = " It is important to note that the precise mechanics of how and when"] # [doc = " a cache gets cleared is an implementation detail."] # [doc = ""] # [doc = " ```"] # [doc = " # if cfg!(miri) { return Ok(()); } // miri takes too long"] # [doc = " use regex_automata::{hybrid::dfa::DFA, Input, MatchError, MatchErrorKind};"] # [doc = ""] # [doc = " // This is a carefully chosen regex. The idea is to pick one"] # [doc = " // that requires some decent number of states (hence the bounded"] # [doc = " // repetition). But we specifically choose to create a class with an"] # [doc = " // ASCII letter and a non-ASCII letter so that we can check that no new"] # [doc = " // states are created once the cache is full. Namely, if we fill up the"] # [doc = " // cache on a haystack of 'a's, then in order to match one 'β', a new"] # [doc = " // state will need to be created since a 'β' is encoded with multiple"] # [doc = " // bytes. Since there's no room for this state, the search should quit"] # [doc = " // at the very first position."] # [doc = " let pattern = r\"[aβ]{100}\";"] # [doc = " let dfa = DFA::builder()"] # [doc = "     .configure("] # [doc = "         // Configure it so that we have the minimum cache capacity"] # [doc = "         // possible. And that if any clearings occur, the search quits."] # [doc = "         DFA::config()"] # [doc = "             .skip_cache_capacity_check(true)"] # [doc = "             .cache_capacity(0)"] # [doc = "             .minimum_cache_clear_count(Some(0)),"] # [doc = "     )"] # [doc = "     .build(pattern)?;"] # [doc = " let mut cache = dfa.create_cache();"] # [doc = ""] # [doc = " // Our search will give up before reaching the end!"] # [doc = " let haystack = \"a\".repeat(101).into_bytes();"] # [doc = " let result = dfa.try_search_fwd(&mut cache, &Input::new(&haystack));"] # [doc = " assert!(matches!("] # [doc = "     *result.unwrap_err().kind(),"] # [doc = "     MatchErrorKind::GaveUp { .. },"] # [doc = " ));"] # [doc = ""] # [doc = " // Now that we know the cache is full, if we search a haystack that we"] # [doc = " // know will require creating at least one new state, it should not"] # [doc = " // be able to make much progress."] # [doc = " let haystack = \"β\".repeat(101).into_bytes();"] # [doc = " let result = dfa.try_search_fwd(&mut cache, &Input::new(&haystack));"] # [doc = " assert!(matches!("] # [doc = "     *result.unwrap_err().kind(),"] # [doc = "     MatchErrorKind::GaveUp { .. },"] # [doc = " ));"] # [doc = ""] # [doc = " // If we reset the cache, then we should be able to create more states"] # [doc = " // and make more progress with searching for betas."] # [doc = " cache.reset(&dfa);"] # [doc = " let haystack = \"β\".repeat(101).into_bytes();"] # [doc = " let result = dfa.try_search_fwd(&mut cache, &Input::new(&haystack));"] # [doc = " assert!(matches!("] # [doc = "     *result.unwrap_err().kind(),"] # [doc = "     MatchErrorKind::GaveUp { .. },"] # [doc = " ));"] # [doc = ""] # [doc = " // ... switching back to ASCII still makes progress since it just needs"] # [doc = " // to set transitions on existing states!"] # [doc = " let haystack = \"a\".repeat(101).into_bytes();"] # [doc = " let result = dfa.try_search_fwd(&mut cache, &Input::new(&haystack));"] # [doc = " assert!(matches!("] # [doc = "     *result.unwrap_err().kind(),"] # [doc = "     MatchErrorKind::GaveUp { .. },"] # [doc = " ));"] # [doc = ""] # [doc = " # Ok::<(), Box<dyn std::error::Error>>(())"] # [doc = " ```"] pub fn minimum_cache_clear_count (mut self , min : Option < usize >) -> Config { self . minimum_cache_clear_count = Some (min) ; self } # [doc = " Configure a lazy DFA search to quit only when its efficiency drops"] # [doc = " below the given minimum."] # [doc = ""] # [doc = " The efficiency of the cache is determined by the number of DFA states"] # [doc = " compiled per byte of haystack searched. For example, if the efficiency"] # [doc = " is 2, then it means the lazy DFA is creating a new DFA state after"] # [doc = " searching approximately 2 bytes in a haystack. Generally speaking, 2"] # [doc = " is quite bad and it's likely that even a slower regex engine like the"] # [doc = " [`PikeVM`](crate::nfa::thompson::pikevm::PikeVM) would be faster."] # [doc = ""] # [doc = " This has no effect if [`Config::minimum_cache_clear_count`] is not set."] # [doc = " Namely, this option only kicks in when the cache has been cleared more"] # [doc = " than the minimum number. If no minimum is set, then the cache is simply"] # [doc = " cleared whenever it fills up and it is impossible for the lazy DFA to"] # [doc = " quit due to ineffective use of the cache."] # [doc = ""] # [doc = " In general, if one is setting [`Config::minimum_cache_clear_count`],"] # [doc = " then one should probably also set this knob as well. The reason is"] # [doc = " that the absolute number of times the cache is cleared is generally"] # [doc = " not a great predictor of efficiency. For example, if a new DFA state"] # [doc = " is created for every 1,000 bytes searched, then it wouldn't be hard"] # [doc = " for the cache to get cleared more than `N` times and then cause the"] # [doc = " lazy DFA to quit. But a new DFA state every 1,000 bytes is likely quite"] # [doc = " good from a performance perspective, and it's likely that the lazy"] # [doc = " DFA should continue searching, even if it requires clearing the cache"] # [doc = " occasionally."] # [doc = ""] # [doc = " Finally, note that if you're implementing your own lazy DFA search"] # [doc = " routine and also want this efficiency check to work correctly, then"] # [doc = " you'll need to use the following routines to record search progress:"] # [doc = ""] # [doc = " * Call [`Cache::search_start`] at the beginning of every search."] # [doc = " * Call [`Cache::search_update`] whenever [`DFA::next_state`] is"] # [doc = " called."] # [doc = " * Call [`Cache::search_finish`] before completing a search. (It is"] # [doc = " not strictly necessary to call this when an error is returned, as"] # [doc = " `Cache::search_start` will automatically finish the previous search"] # [doc = " for you. But calling it where possible before returning helps improve"] # [doc = " the accuracy of how many bytes have actually been searched.)"] pub fn minimum_bytes_per_state (mut self , min : Option < usize >) -> Config { self . minimum_bytes_per_state = Some (min) ; self } # [doc = " Returns the match semantics set in this configuration."] pub fn get_match_kind (& self) -> MatchKind { self . match_kind . unwrap_or (MatchKind :: LeftmostFirst) } # [doc = " Returns the prefilter set in this configuration, if one at all."] pub fn get_prefilter (& self) -> Option < & Prefilter > { self . pre . as_ref () . unwrap_or (& None) . as_ref () } # [doc = " Returns whether this configuration has enabled anchored starting states"] # [doc = " for every pattern in the DFA."] pub fn get_starts_for_each_pattern (& self) -> bool { self . starts_for_each_pattern . unwrap_or (false) } # [doc = " Returns whether this configuration has enabled byte classes or not."] # [doc = " This is typically a debugging oriented option, as disabling it confers"] # [doc = " no speed benefit."] pub fn get_byte_classes (& self) -> bool { self . byte_classes . unwrap_or (true) } # [doc = " Returns whether this configuration has enabled heuristic Unicode word"] # [doc = " boundary support. When enabled, it is possible for a search to return"] # [doc = " an error."] pub fn get_unicode_word_boundary (& self) -> bool { self . unicode_word_boundary . unwrap_or (false) } # [doc = " Returns whether this configuration will instruct the lazy DFA to enter"] # [doc = " a quit state whenever the given byte is seen during a search. When at"] # [doc = " least one byte has this enabled, it is possible for a search to return"] # [doc = " an error."] pub fn get_quit (& self , byte : u8) -> bool { self . quitset . map_or (false , | q | q . contains (byte)) } # [doc = " Returns whether this configuration will instruct the lazy DFA to"] # [doc = " \"specialize\" start states. When enabled, the lazy DFA will tag start"] # [doc = " states so that search routines using the lazy DFA can detect when"] # [doc = " it's in a start state and do some kind of optimization (like run a"] # [doc = " prefilter)."] pub fn get_specialize_start_states (& self) -> bool { self . specialize_start_states . unwrap_or (false) } # [doc = " Returns the cache capacity set on this configuration."] pub fn get_cache_capacity (& self) -> usize { self . cache_capacity . unwrap_or (2 * (1 << 20)) } # [doc = " Returns whether the cache capacity check should be skipped."] pub fn get_skip_cache_capacity_check (& self) -> bool { self . skip_cache_capacity_check . unwrap_or (false) } # [doc = " Returns, if set, the minimum number of times the cache must be cleared"] # [doc = " before a lazy DFA search can give up. When no minimum is set, then a"] # [doc = " search will never quit and will always clear the cache whenever it"] # [doc = " fills up."] pub fn get_minimum_cache_clear_count (& self) -> Option < usize > { self . minimum_cache_clear_count . unwrap_or (None) } # [doc = " Returns, if set, the minimum number of bytes per state that need to be"] # [doc = " processed in order for the lazy DFA to keep going. If the minimum falls"] # [doc = " below this number (and the cache has been cleared a minimum number of"] # [doc = " times), then the lazy DFA will return a \"gave up\" error."] pub fn get_minimum_bytes_per_state (& self) -> Option < usize > { self . minimum_bytes_per_state . unwrap_or (None) } # [doc = " Returns the minimum lazy DFA cache capacity required for the given NFA."] # [doc = ""] # [doc = " The cache capacity required for a particular NFA may change without"] # [doc = " notice. Callers should not rely on it being stable."] # [doc = ""] # [doc = " This is useful for informational purposes, but can also be useful for"] # [doc = " other reasons. For example, if one wants to check the minimum cache"] # [doc = " capacity themselves or if one wants to set the capacity based on the"] # [doc = " minimum."] # [doc = ""] # [doc = " This may return an error if this configuration does not support all of"] # [doc = " the instructions used in the given NFA. For example, if the NFA has a"] # [doc = " Unicode word boundary but this configuration does not enable heuristic"] # [doc = " support for Unicode word boundaries."] pub fn get_minimum_cache_capacity (& self , nfa : & thompson :: NFA ,) -> Result < usize , BuildError > { let quitset = self . quit_set_from_nfa (nfa) ? ; let classes = self . byte_classes_from_nfa (nfa , & quitset) ; let starts = self . get_starts_for_each_pattern () ; Ok (minimum_cache_capacity (nfa , & classes , starts)) } # [doc = " Returns the byte class map used during search from the given NFA."] # [doc = ""] # [doc = " If byte classes are disabled on this configuration, then a map is"] # [doc = " returned that puts each byte in its own equivalent class."] fn byte_classes_from_nfa (& self , nfa : & thompson :: NFA , quit : & ByteSet ,) -> ByteClasses { if ! self . get_byte_classes () { ByteClasses :: singletons () } else { let mut set = nfa . byte_class_set () . clone () ; if ! quit . is_empty () { set . add_set (& quit) ; } set . byte_classes () } } # [doc = " Return the quit set for this configuration and the given NFA."] # [doc = ""] # [doc = " This may return an error if the NFA is incompatible with this"] # [doc = " configuration's quit set. For example, if the NFA has a Unicode word"] # [doc = " boundary and the quit set doesn't include non-ASCII bytes."] fn quit_set_from_nfa (& self , nfa : & thompson :: NFA ,) -> Result < ByteSet , BuildError > { let mut quit = self . quitset . unwrap_or (ByteSet :: empty ()) ; if nfa . look_set_any () . contains_word_unicode () { if self . get_unicode_word_boundary () { for b in 0x80 ..= 0xFF { quit . add (b) ; } } else { if ! quit . contains_range (0x80 , 0xFF) { return Err (BuildError :: unsupported_dfa_word_boundary_unicode () ,) ; } } } Ok (quit) } # [doc = " Overwrite the default configuration such that the options in `o` are"] # [doc = " always used. If an option in `o` is not set, then the corresponding"] # [doc = " option in `self` is used. If it's not set in `self` either, then it"] # [doc = " remains not set."] fn overwrite (& self , o : Config) -> Config { Config { match_kind : o . match_kind . or (self . match_kind) , pre : o . pre . or_else (| | self . pre . clone ()) , starts_for_each_pattern : o . starts_for_each_pattern . or (self . starts_for_each_pattern) , byte_classes : o . byte_classes . or (self . byte_classes) , unicode_word_boundary : o . unicode_word_boundary . or (self . unicode_word_boundary) , quitset : o . quitset . or (self . quitset) , specialize_start_states : o . specialize_start_states . or (self . specialize_start_states) , cache_capacity : o . cache_capacity . or (self . cache_capacity) , skip_cache_capacity_check : o . skip_cache_capacity_check . or (self . skip_cache_capacity_check) , minimum_cache_clear_count : o . minimum_cache_clear_count . or (self . minimum_cache_clear_count) , minimum_bytes_per_state : o . minimum_bytes_per_state . or (self . minimum_bytes_per_state) , } } }
    };
}

impl_242!()